{
    if(48 == key)
    {
        //Button_OK
        //When hardware button 48 clicked call virtual function
        //Call WidgetScrolling
        WidgetScrolling();
    
    }

    if(49 == key)
    {
        //Button_Right
        //When hardware button 49 clicked call virtual function
        //Call WidgetScrolling
        WidgetScrolling();
    
    }

    if(50 == key)
    {
        //Button_Left
        //When hardware button 50 clicked call virtual function
        //Call WidgetScrolling
        WidgetScrolling();
    
    }
}
